s=s.replace('<div class="v2-controls">','''<div class="alert-status" id="alert-status" role="status" aria-live="polite"><span class="alert-dot"></span><span id="alert-summary">気象庁の警報・注意報を確認しています…</span><button id="refresh-alerts" type="button">↻ 更新</button></div><div class="alert-options"><label><input type="checkbox" id="show-alerts" checked/> 警報・注意報を地図に表示</label><label><input type="checkbox" id="show-advisories"/> 注意報も表示</label><span>※ 気象警報・注意報であり、災害発生や避難指示を示すものではありません。</span></div><div id="alert-region-list" class="alert-region-list" aria-live="polite"></div><div class="v2-controls">''')
s=s.replace('<span>● 地点情報</span>','<span>● 自治体ポイント ／ <span class="alert-legend">● 警報情報</span></span>')
